import{_ as s,o as a,c as i,a0 as t}from"./chunks/framework.C3yZ6M33.js";const k=JSON.parse('{"title":"Run a node","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/run-a-node.md","filePath":"how-to/run-a-node.md"}'),n={name:"how-to/run-a-node.md"};function o(d,e,h,p,r,l){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="run-a-node" tabindex="-1">Run a node <a class="header-anchor" href="#run-a-node" aria-label="Permalink to &quot;Run a node&quot;">​</a></h1><p>This guide shows how to run <code>peregrin serve</code> — the machine daemon that hosts the session plane and answers <code>/api/*</code> for the hub and CLI.</p><h2 id="basics" tabindex="-1">Basics <a class="header-anchor" href="#basics" aria-label="Permalink to &quot;Basics&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">peregrin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span></code></pre></div><p>Binds <code>PEREGRIN_HOST:PEREGRIN_PORT</code> — default <code>127.0.0.1:8787</code>. Check it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">peregrin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">peregrin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # identity, agents, capabilities</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">peregrin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sessions</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>Loopback binds need no token. For anything reachable off-machine:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PEREGRIN_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">shared-secret</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">peregrin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span></code></pre></div><p>Non-loopback without <code>PEREGRIN_TOKEN</code> refuses to start. Clients send it as a bearer token; the hub uses <code>PEREGRIN_NODE_TOKEN</code> per node.</p><h2 id="pairing" tabindex="-1">Pairing <a class="header-anchor" href="#pairing" aria-label="Permalink to &quot;Pairing&quot;">​</a></h2><p>The web UI exchanges a short-lived code for a bearer token:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">peregrin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pair</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # prints a code on the node</span></span></code></pre></div><p>Then <code>peregrin redeem &lt;code&gt;</code> (or the UI&#39;s pair flow) trades it for a token. <code>/api/pair</code> is rate-limited — <code>PEREGRIN_PAIR_LIMIT_PER_MIN</code> / <code>_PER_DAY</code>.</p><h2 id="the-session-plane" tabindex="-1">The session plane <a class="header-anchor" href="#the-session-plane" aria-label="Permalink to &quot;The session plane&quot;">​</a></h2><p>By default the node runs the session plane as a managed subprocess — it spawns <code>sepia serve</code>, handshakes <code>manifest</code>, and respawns it once on death. <code>SEPIA_*</code> env vars (driver dirs, <code>SEPIA_DEVIN_DB</code>, lock TTLs) are read by the sepia child — export them on the node. <code>PEREGRIN_SEPIA</code> overrides binary discovery when needed.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PEREGRIN_SEPIA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/path/to/sepia   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># optional override for discovery</span></span></code></pre></div><p>For dev you can link sepia in-process instead (the <code>LocalPlane</code> test mode) — same <code>SessionPlane</code> surface, no subprocess:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PEREGRIN_SESSION_PLANE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">local    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or: inprocess</span></span></code></pre></div><h2 id="node-identity-and-state" tabindex="-1">Node identity and state <a class="header-anchor" href="#node-identity-and-state" aria-label="Permalink to &quot;Node identity and state&quot;">​</a></h2><ul><li><code>PEREGRIN_HOME</code> — node data dir (<code>~/.local/share/peregrin</code> default): <code>node.json</code>, <code>meta.json</code>, <code>tokens.json</code>.</li><li><code>PEREGRIN_NODE</code> — override the identity file path.</li><li><code>PEREGRIN_NAME</code> — display name for <code>GET /api/node</code> and the hub.</li><li><code>PEREGRIN_META</code> / <code>PEREGRIN_META_PATH</code> — the overlay store file (pins, archives, spans).</li></ul><h2 id="systemd" tabindex="-1">systemd <a class="header-anchor" href="#systemd" aria-label="Permalink to &quot;systemd&quot;">​</a></h2><p><code>peregrin-service</code> + <code>peregrin-systemd</code> are the service port and adapter — a unit file keeps the node alive and restarts it. <code>peregrin service install</code> writes + enables the unit (<code>--hub</code> manages the hub, <code>--system</code> a system unit); <code>peregrin service disable</code> stops it and keeps it stopped across logins (unit file kept) until <code>peregrin service enable</code>. <code>status</code>, <code>restart</code> and <code>logs</code> round out the verbs.</p>`,23)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
